interface Visitor { fun visitDefault(e: Element) }
interface UnionVisitor : Visitor { fun visitUnion(u: UnionShape) }   // extended protocol
class UnionShape(val a: Element, val b: Element) : Element {
    override fun accept(v: Visitor) =
        if (v is UnionVisitor) v.visitUnion(this)      // capability check
        else v.visitDefault(this)                      // visitor that predates UnionShape
}

open class Area : Visitor { override fun visitDefault(e: Element) = Unit }
class UnionArea(private val base: Area) : Visitor by base, UnionVisitor {
    override fun visitUnion(u: UnionShape) { u.a.accept(this); u.b.accept(this) }
}
